import { Suspense } from 'react'
import { CardStats } from './CardStats'
import { RevenueChart } from './RevenueChart'
import { LatestInvoices } from './LatestInvoices'

async function getDashboardData() {
  const res = await fetch('https://api.example.com/dashboard')
  return res.json()
}

async function CardStatsWrapper() {
  const data = await getDashboardData()
  return (
    <CardStats
      totalRevenue={data.totalRevenue}
      totalInvoices={data.totalInvoices}
    />
  )
}

async function RevenueChartWrapper() {
  const data = await getDashboardData()
  return <RevenueChart revenue={data.revenue} />
}

async function LatestInvoicesWrapper() {
  const data = await getDashboardData()
  return <LatestInvoices invoices={data.invoices} />
}

function CardStatsFallback() {
  return (
    <div className="grid">
      <div className="card skeleton">
        <p>Loading stats...</p>
      </div>
      <div className="card skeleton">
        <p>Loading stats...</p>
      </div>
    </div>
  )
}

function RevenueChartFallback() {
  return (
    <div className="chart skeleton">
      <p>Loading chart...</p>
    </div>
  )
}

function LatestInvoicesFallback() {
  return (
    <div className="invoices skeleton">
      <p>Loading invoices...</p>
    </div>
  )
}

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<CardStatsFallback />}>
        <CardStatsWrapper />
      </Suspense>
      <Suspense fallback={<RevenueChartFallback />}>
        <RevenueChartWrapper />
      </Suspense>
      <Suspense fallback={<LatestInvoicesFallback />}>
        <LatestInvoicesWrapper />
      </Suspense>
    </main>
  )
}

